def run(ctx: NodeContext):
    """合并：把多路结果按顺序拼成一段。"""
    items = ctx.input if isinstance(ctx.input, list) else [ctx.text]
    sep = ctx.params.get("separator") or "\n\n"
    return sep.join(str(i) for i in items)

